def extras(code):
    result={}
    for prefix,keys,values in [("category_",CATEGORY_KEYS,CATEGORIES),("",QUICK_KEYS,QUICK),("check_",CHECK_KEYS,CHECK)]:
        entries=values[code].split("|")
        assert len(keys)==len(entries)
        result.update({prefix+k:v for k,v in zip(keys,entries)})
    result.update(QUICK_CONTROLS[code])
    return result
